const FilterComp = (props) => {
    const {det} = props
    console.log(det)
    return(
        <div>
            {det.map((details)=>{
                return <>
                <h6>{details.heading}</h6>
                {details?.titles?.map((val)=>
                    <p>val</p>
                )}
                </>
            })}
        </div>
    )
}

export default FilterComp
